// A channel is identified by a name, and the name must match exactly
// on both sides. A reverse-domain prefix avoids collisions with plugins.
const channel = MethodChannel('com.app/device');

// Always await: the reply has to travel
final level = await channel.invokeMethod<int>('batteryLevel');

// What fits in the envelope: num, String, bool, List, Map, Uint8List
await channel.invokeMethod('save', {'id': 7, 'name': 'Ada'});

// What does NOT fit: your own classes
// await channel.invokeMethod('save', user);  // crashes at runtime

// Dart — handling both failure shapes
try {
  final level = await channel.invokeMethod<int>('batteryLevel');
} on PlatformException catch (e) {
  // The native side replied with error(): a real failure
  debugPrint('failed: ${e.code} ${e.message}');
} on MissingPluginException {
  // No handler for that name: usually a typo, or a missing platform
}

// Swift — one reply per path, and heavy work off the main thread
let channel = FlutterMethodChannel(name: "com.app/device",
                                   binaryMessenger: controller.binaryMessenger)
channel.setMethodCallHandler { call, result in
  switch call.method {
  case "batteryLevel":
    let level = UIDevice.current.batteryLevel
    if level < 0 { result(FlutterError(code: "unavailable",
                                       message: "No battery on this device",
                                       details: nil)) }
    else { result(Int(level * 100)) }
  default:
    result(FlutterMethodNotImplemented)   // never leave a path silent
  }
}

