const events = EventChannel('com.app/connectivity');
StreamSubscription<dynamic>? sub;

@override
void initState() {
  super.initState();
  sub = events.receiveBroadcastStream().listen(
        (status) => setState(() => _status = status as String),
        onError: (e) => debugPrint('stream failed: $e'),
      );
}

@override
void dispose() {
  sub?.cancel();   // this is what triggers onCancel on the native side
  super.dispose();
}

// Kotlin — start in onListen, stop in onCancel
EventChannel(messenger, "com.app/connectivity").setStreamHandler(
  object : EventChannel.StreamHandler {
    private var callback: ConnectivityManager.NetworkCallback? = null

    override fun onListen(args: Any?, sink: EventChannel.EventSink) {
      callback = register { status -> sink.success(status) }
    }

    override fun onCancel(args: Any?) {
      callback?.let { unregister(it) }   // forget this and the radio stays on
      callback = null
    }
  }
)

